// Initialize TBox with safe defaults and fuzzed mode/build.
// Requirements enforcement:
// - priv: use nullptr for non-Android platforms as documented.
// - allocator: pass nullptr to select default allocator based on mode.
// - mode: fuzzed value; library interprets according to its build.
// - build: fuzzed value; typically TB_VERSION_BUILD. We supply a randomized value within 64-bit range.
// - On failure (tb_false), we must not treat TBox as initialized and we bail.

// Use defaults for platform/allocator per docs
tb_handle_t priv = (tb_handle_t)nullptr;
tb_allocator_ref_t allocator = (tb_allocator_ref_t)nullptr;

// Fuzz mode/build within reasonable ranges
// Keep mode small to exercise branching without triggering extreme behaviors
// (library will mask/interpret flags internally).
tb_size_t mode = (tb_size_t)(*FUZZ_PARAM(unsigned int) & 0x3u); // sample a few low bits
// Build number as arbitrary 64-bit value; library may ignore mismatches.
tb_hize_t build = (tb_hize_t)(*FUZZ_PARAM(unsigned long long));

// Call initializer
tb_bool_t ok = tb_init_(priv, allocator, mode, build);
if (!ok) {
    // Not initialized; do not allow subsequent API usage this round
    FUZZ_SET_ATTR_INT_GLOBAL("tbox_inited", 0);
    FUZZ_BAIL();
}

// Mark library as initialized for subsequent stubs
FUZZ_SET_ATTR_INT_GLOBAL("tbox_inited", 1);

// Validation: tb_init_ success recorded globally; no persistent objects to output.

// Enforce correct lifetime: only call tb_exit after a successful tb_init_.
int inited = FUZZ_GET_ATTR_INT_GLOBAL("tbox_inited");
if (!inited) {
    FUZZ_BAIL();
}

// Invoke shutdown; after this, no TBox API should be used until re-init.
tb_exit();

// Clear initialization state
FUZZ_SET_ATTR_INT_GLOBAL("tbox_inited", 0);

// Validation: ensures tb_exit is only executed after init; resets global state.

// tb_state should be called only after successful initialization.
int inited = FUZZ_GET_ATTR_INT_GLOBAL("tbox_inited");
if (!inited) {
    FUZZ_BAIL();
}

// Query state; we do not assert specific enumerants here as they are library-defined.
volatile tb_size_t state_val = tb_state();
(void)state_val;

// Validation: guarded by init-state check; side-effect free and no persistent outputs.
